import{_ as a,o as i,c as t,ag as l}from"./chunks/framework.DJVIMu25.js";const p=JSON.parse('{"title":"音乐播放器","description":"","frontmatter":{"title":"音乐播放器"},"headers":[],"relativePath":"zh_Hans/guides/music.md","filePath":"zh_Hans/guides/music.md","lastUpdated":1786545590000}'),o={name:"zh_Hans/guides/music.md"};function c(r,e,s,d,n,u){return i(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="音乐播放器" tabindex="-1">音乐播放器 <a class="header-anchor" href="#音乐播放器" aria-label="Permalink to &quot;音乐播放器&quot;">​</a></h1><p>JoyMart 内置了一个后台音乐播放器，通过 Minecraft 原生的音符盒声音播放 NBS（Note Block Studio）歌曲 —— 无需任何资源包。</p><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><ul><li>歌曲从 <code>plugins/JoyMart/music/</code> 目录中的 <code>.nbs</code> 文件加载</li><li><code>NbsSong</code> 解析器提取节拍以及每个 tick 的音符</li><li>每位玩家拥有一个独立的定时任务，按歌曲节拍一次推进一个 NBS tick</li><li>每个音符通过 <code>Player#playSound</code> 使用 Minecraft 内置的音符盒声音播放（如 <code>BLOCK_NOTE_BLOCK_HARP</code>、<code>BLOCK_NOTE_BLOCK_BASS</code> 等）</li><li>每位玩家拥有各自的定时任务和播放状态，因此不同玩家可以同时收听不同的歌曲</li></ul><h2 id="nbs-节拍与-tick-调度" tabindex="-1">NBS 节拍与 tick 调度 <a class="header-anchor" href="#nbs-节拍与-tick-调度" aria-label="Permalink to &quot;NBS 节拍与 tick 调度&quot;">​</a></h2><ul><li>NBS 节拍以 ticks-per-second × 100 的形式存储（即 <code>1000</code> 表示 10 tps）</li><li>服务器以 20 ticks/秒 运行，因此一个 NBS tick 需要 <code>2000 / tempo</code> 个服务器 tick</li><li>该比值会四舍五入到最接近的整数 tick，并作为 <code>runTaskTimer</code> 的周期使用</li><li>节拍不超过 2000（20 tps）时为精确值；更高的节拍会略微变慢（每个 NBS tick 向上取整为 1 个服务器 tick）</li></ul><div class="warning custom-block"><p class="custom-block-title">注意</p><p>由于服务器固定以 20 ticks/秒 运行，节拍高于 2000（即 20 tps）的歌曲无法被精确还原，实际播放速度会略低于设定值。</p></div><h2 id="添加歌曲" tabindex="-1">添加歌曲 <a class="header-anchor" href="#添加歌曲" aria-label="Permalink to &quot;添加歌曲&quot;">​</a></h2><ol><li>获取 <code>.nbs</code> 文件（使用 <a href="https://onlinesequencer.net/" target="_blank" rel="noreferrer">Open Note Block Studio</a> 或类似工具创建）</li><li>将它们放入 <code>plugins/JoyMart/music/</code> 目录</li><li>重启服务器，或运行 <code>/gba reload</code></li><li>玩家可从 JoyMart 主菜单访问音乐播放器 GUI</li></ol><h2 id="音乐播放器-gui" tabindex="-1">音乐播放器 GUI <a class="header-anchor" href="#音乐播放器-gui" aria-label="Permalink to &quot;音乐播放器 GUI&quot;">​</a></h2><ul><li>从 JoyMart 主菜单进入</li><li>显示已加载的歌曲列表</li><li>玩家可以独立地播放、停止和切换歌曲</li><li>如果 NBS 文件内没有标题，歌曲名称会回退为文件名（不含扩展名）</li></ul><div class="tip custom-block"><p class="custom-block-title">提示</p><p>每位玩家的播放状态相互独立，因此多名玩家可同时收听不同的曲目，互不影响。</p></div><h2 id="灵感来源" tabindex="-1">灵感来源 <a class="header-anchor" href="#灵感来源" aria-label="Permalink to &quot;灵感来源&quot;">​</a></h2><p>音乐播放器的灵感来自 <a href="https://www.spigotmc.org/resources/jukebox-music-plugin.40580/" target="_blank" rel="noreferrer">JukeBox - Music Plugin</a>。JoyMart 的实现是完全独立从头编写的 —— NBS 解析、每玩家调度以及 GUI 均为原创代码。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./getting-started">快速开始</a></li><li><a href="./games">游戏模式</a></li></ul>',16)])])}const k=a(o,[["render",c]]);export{p as __pageData,k as default};
